    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False
    prime_factors = 0
    for i in range(2, int(sqrt(a)) + 1):
        if a % i == 0:
            if is_prime(i):
                prime_factors += 1
            if is_prime(a // i):
                prime_factors += 1
            if prime_factors > 3:
                return False
    return prime_factors == 3
